import { handleFacodiMechanism } from '../_shared/facodi-mechanism.ts';

Deno.serve((req) => handleFacodiMechanism(req, {
  functionName: 'v2_push_odoo_learning_object',
  jobType: 'push_odoo_learning_object',
  kind: 'odoo',
}));

import { createClient } from 'npm:@supabase/supabase-js@2.45.4';
import { errorResponse, jsonResponse, optionsResponse } from './http.ts';
import { checkEdgeRateLimit } from './rate-limit.ts';

type MechanismKind = 'analysis' | 'odoo';
type ServiceClient = { schema: (schema: string) => { rpc: (functionName: string, args: Record<string, unknown>) => Promise<{ data: unknown; error: { message?: string } | null }> }; rpc: (functionName: string, args: Record<string, unknown>) => Promise<{ data: unknown; error: { message?: string } | null }> };
export type FacodiMechanismOptions = { functionName: string; jobType: string; kind?: MechanismKind };
const DEFAULT_RATE_LIMIT_WINDOWS = [{ windowSeconds: 60, maxRequests: 10 }, { windowSeconds: 24 * 60 * 60, maxRequests: 100 }];
function stringValue(value: unknown) { return typeof value === 'string' && value.trim() ? value.trim() : null; }
function objectIdFromBody(body: Record<string, unknown>) { return stringValue(body.learning_object_id) ?? stringValue(body.object_id); }
function rpcRecord(value: unknown) { if (Array.isArray(value)) return value[0] && typeof value[0] === 'object' ? value[0] as Record<string, unknown> : null; return value && typeof value === 'object' ? value as Record<string, unknown> : null; }
async function getAuthenticatedUser(req: Request, supabaseUrl: string, anonKey: string) { const authHeader = req.headers.get('Authorization'); if (!authHeader) return { user: null, error: 'Missing authorization header' }; const supabase = createClient(supabaseUrl, anonKey, { global: { headers: { Authorization: authHeader } }, auth: { persistSession: false } }); const { data, error } = await supabase.auth.getUser(); if (error || !data.user) return { user: null, error: error?.message ?? 'Invalid token' }; return { user: data.user, error: null }; }
async function createAnalysisJob(params: { supabase: ServiceClient; body: Record<string, unknown>; jobType: string; requestId: string; userId: string }) { const { data, error } = await params.supabase.schema('facodi').rpc('queue_analysis_job', { p_learning_object_id: objectIdFromBody(params.body), p_video_id: stringValue(params.body.video_id), p_youtube_video_id: stringValue(params.body.youtube_video_id), p_input_url: stringValue(params.body.url) ?? stringValue(params.body.youtube_url), p_job_type: params.jobType, p_current_step: 'queued', p_requested_by: params.userId, p_request_source: params.jobType, p_input_payload: { ...params.body, requestId: params.requestId } }); if (error) throw new Error(error.message); return rpcRecord(data); }
async function createOdooJob(params: { supabase: ServiceClient; body: Record<string, unknown>; jobType: string; userId: string }) { const { data, error } = await params.supabase.schema('facodi').rpc('queue_odoo_sync_job', { p_instance_id: stringValue(params.body.instance_id), p_learning_object_id: objectIdFromBody(params.body), p_odoo_record_id: stringValue(params.body.odoo_record_id), p_job_type: params.jobType, p_requested_by: params.userId, p_payload: params.body }); if (error) throw new Error(error.message); return rpcRecord(data); }
export async function handleFacodiMechanism(req: Request, options: FacodiMechanismOptions) { const requestId = crypto.randomUUID(); if (req.method === 'OPTIONS') return optionsResponse(req); if (req.method !== 'POST') return errorResponse(req, 405, 'METHOD_NOT_ALLOWED', 'Method not allowed', { requestId }); const supabaseUrl = Deno.env.get('SUPABASE_URL'); const anonKey = Deno.env.get('SUPABASE_ANON_KEY'); const serviceRoleKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY'); if (!supabaseUrl || !anonKey || !serviceRoleKey) return errorResponse(req, 500, 'MISSING_SUPABASE_ENV', 'Missing Supabase environment variables', { requestId }); const { user, error: authError } = await getAuthenticatedUser(req, supabaseUrl, anonKey); if (!user) { if (authError) console.warn(`[${options.functionName}] ${requestId} auth failed: ${authError}`); return errorResponse(req, 401, 'UNAUTHORIZED', 'Invalid or expired authorization token', { requestId }); } let body: Record<string, unknown>; try { const parsed = await req.json(); body = parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed as Record<string, unknown> : {}; } catch { return errorResponse(req, 400, 'INVALID_JSON', 'Invalid JSON body', { requestId }); } const supabase = createClient(supabaseUrl, serviceRoleKey, { auth: { persistSession: false } }) as unknown as ServiceClient; try { const rateLimit = await checkEdgeRateLimit(supabase, { functionName: options.functionName, userId: user.id, windows: DEFAULT_RATE_LIMIT_WINDOWS }); if (!rateLimit.allowed) return errorResponse(req, 429, 'RATE_LIMITED', 'Too many FACODI mechanism requests. Try again later.', { requestId, retryAfterSeconds: rateLimit.retryAfterSeconds }); const job = options.kind === 'odoo' ? await createOdooJob({ supabase, body, jobType: options.jobType, userId: user.id }) : await createAnalysisJob({ supabase, body, jobType: options.jobType, requestId, userId: user.id }); if (!job) throw new Error('Job insert returned no row'); return jsonResponse(req, { requestId, status: 'queued', mechanism: options.functionName, jobType: options.jobType, jobId: job.id }, 202); } catch (error) { const message = error instanceof Error ? error.message : 'Could not queue FACODI mechanism'; console.error(`[${options.functionName}] ${requestId} failed: ${message}`); return errorResponse(req, 500, 'QUEUE_FAILED', 'Could not queue FACODI mechanism', { requestId, details: message }); } }

export type JsonBody = Record<string, unknown> | Array<unknown>;
const defaultAllowedOrigins = ['https://tube.open2.tech', 'https://facodi.com', 'https://facodi.pt', 'https://open2.tech', 'http://localhost:8080', 'http://127.0.0.1:8080'];
function configuredAllowedOrigins() { const configured = Deno.env.get('ALLOWED_ORIGIN') || Deno.env.get('ALLOWED_ORIGINS'); if (!configured) return defaultAllowedOrigins; return configured.split(',').map((origin) => origin.trim()).filter(Boolean); }
export function corsHeadersForRequest(req: Request): Record<string, string> { const allowedOrigins = configuredAllowedOrigins(); const requestOrigin = req.headers.get('origin'); const allowAll = allowedOrigins.includes('*'); const allowedOrigin = allowAll ? '*' : requestOrigin && allowedOrigins.includes(requestOrigin) ? requestOrigin : allowedOrigins[0] ?? 'https://tube.open2.tech'; return { 'Access-Control-Allow-Origin': allowedOrigin, 'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type', 'Access-Control-Allow-Methods': 'POST, OPTIONS', 'Vary': 'Origin' }; }
export function jsonResponse(req: Request, body: JsonBody, status = 200) { return new Response(JSON.stringify(body), { status, headers: { ...corsHeadersForRequest(req), 'Content-Type': 'application/json' } }); }
export function errorResponse(req: Request, status: number, code: string, message: string, details: Record<string, unknown> = {}) { return jsonResponse(req, { error: { code, message, ...details } }, status); }
export function optionsResponse(req: Request) { return new Response(null, { status: 204, headers: corsHeadersForRequest(req) }); }

type SupabaseRpcClient = { rpc: (functionName: string, args: Record<string, unknown>) => Promise<{ data: unknown; error: { message?: string } | null }> };
export type RateLimitWindow = { windowSeconds: number; maxRequests: number };
export type RateLimitDecision = { allowed: boolean; requestCount: number; retryAfterSeconds: number };
function firstRow(value: unknown): Record<string, unknown> | null { if (Array.isArray(value)) return value[0] && typeof value[0] === 'object' ? value[0] as Record<string, unknown> : null; return value && typeof value === 'object' ? value as Record<string, unknown> : null; }
function numberValue(value: unknown, fallback: number) { return typeof value === 'number' && Number.isFinite(value) ? value : fallback; }
export async function checkEdgeRateLimit(supabaseServiceRole: SupabaseRpcClient, params: { functionName: string; userId: string; windows: RateLimitWindow[] }): Promise<RateLimitDecision> { for (const window of params.windows) { const { data, error } = await supabaseServiceRole.rpc('check_edge_rate_limit', { p_function_name: params.functionName, p_subject_id: params.userId, p_window_seconds: window.windowSeconds, p_max_requests: window.maxRequests }); if (error) throw new Error(`Rate limit check failed: ${error.message ?? 'unknown error'}`); const row = firstRow(data); if (!row) throw new Error('Rate limit check returned no result'); const decision = { allowed: row.allowed === true, requestCount: numberValue(row.request_count, 0), retryAfterSeconds: numberValue(row.retry_after_seconds, window.windowSeconds) }; if (!decision.allowed) return decision; } return { allowed: true, requestCount: 0, retryAfterSeconds: 0 }; }
